UPDATE sys_org
SET delete_flag = id, deleted_at = #{deletedAt}
WHERE id IN

    #{id}

AND delete_flag = 0 AND tenant_id = #{tenantId}

mapper.select:
WITH RECURSIVE starting_points AS ( SELECT id AS root_id FROM sys_org WHERE id IN
#{orgId}
AND tenant_id = #{tenantId} AND delete_flag = 0 ), descendants AS ( SELECT sp.root_id, o.id AS descendant_id, o.parent_id FROM sys_org o INNER JOIN starting_points sp ON o.id = sp.root_id WHERE o.tenant_id = #{tenantId} AND o.delete_flag = 0 UNION ALL SELECT d.root_id, o.id AS descendant_id, o.parent_id FROM sys_org o INNER JOIN descendants d ON o.parent_id = d.descendant_id WHERE o.tenant_id = #{tenantId} AND o.delete_flag = 0 ) SELECT root_id AS orgId, descendant_id AS descendantId FROM descendants
